package com.fooddelivery.mail.entity;import jakarta.persistence.*;import java.time.LocalDateTime;@Entity @Table(name="mail_deliveries") public class MailDelivery{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="recipient",nullable=false,length=320)private String recipient;@Column(name="subject",nullable=false,length=200)private String subject;@Column(name="status",nullable=false,length=20)private String status;@Column(name="error_message",length=1000)private String errorMessage;@Column(name="created_at",insertable=false,updatable=false)private LocalDateTime createdAt;protected MailDelivery(){}public MailDelivery(String to,String subject,String status,String error){recipient=to;this.subject=subject;this.status=status;errorMessage=error;}public Long getId(){return id;}public String getRecipient(){return recipient;}public String getSubject(){return subject;}public String getStatus(){return status;}public String getErrorMessage(){return errorMessage;}public LocalDateTime getCreatedAt(){return createdAt;}}
